draw:
const m1 = p.m1, m2 = p.m2, x2 = p.x2;
const xcm = (m1 * 0 + m2 * x2) / (m1 + m2);
const L = 10;                      // metres shown
const x0 = W * 0.10, x1 = W * 0.92;
const sx = function (xm) { return x0 + (x1 - x0) * xm / L; };
const beamY = H * 0.52;
const tilt = Math.sin(t * 1.4) * 0.012;   // gentle wobble about the pivot

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";

// axis
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, H * 0.86); ctx.lineTo(x1, H * 0.86); ctx.stroke();
ctx.fillStyle = C.faint;
for (let k = 0; k <= L; k += 2) {
  const xx = sx(k);
  ctx.beginPath(); ctx.moveTo(xx, H * 0.86); ctx.lineTo(xx, H * 0.89); ctx.stroke();
  ctx.fillText(k + " m", xx, H * 0.97);
}

// pivot under the centre of mass
const px = sx(xcm);
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.moveTo(px, beamY + 10); ctx.lineTo(px - 12, beamY + 34); ctx.lineTo(px + 12, beamY + 34);
ctx.closePath(); ctx.fill();

// beam, tilted a touch about the pivot
ctx.save();
ctx.translate(px, beamY);
ctx.rotate(tilt);
ctx.fillStyle = C.figure;
ctx.fillRect(x0 - px, -3, x1 - x0, 6);

const r1 = 6 + 14 * Math.sqrt(m1 / 10);
const r2 = 6 + 14 * Math.sqrt(m2 / 10);
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(sx(0) - px, -3 - r1, r1, 0, 6.284); ctx.fill();
ctx.beginPath(); ctx.arc(sx(x2) - px, -3 - r2, r2, 0, 6.284); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText(m1.toFixed(1), sx(0) - px, -3 - r1 + 4);
ctx.fillText(m2.toFixed(1), sx(x2) - px, -3 - r2 + 4);
ctx.restore();

// centre-of-mass marker
ctx.strokeStyle = C.accent; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(px, H * 0.12); ctx.lineTo(px, beamY + 8); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("centre of mass", px, H * 0.09);

// lever arms
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
const ay = beamY + 46;
ctx.beginPath(); ctx.moveTo(sx(0), ay); ctx.lineTo(px, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, ay); ctx.lineTo(sx(x2), ay); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("d1 = " + xcm.toFixed(2) + " m", (sx(0) + px) / 2, ay - 6);
ctx.fillText("d2 = " + (x2 - xcm).toFixed(2) + " m", (px + sx(x2)) / 2, ay - 6);

out.note = "x_cm = " + xcm.toFixed(3) + " m    m1*d1 = " + (m1 * xcm).toFixed(2) +
  " kg m,  m2*d2 = " + (m2 * (x2 - xcm)).toFixed(2) + " kg m";
